	('dddc7943-2739-48be-96c3-2ebdaabe84d7', 'App\\Notifications\\UpdateKontrakNotification', 'App\\Models\\User', 17, '{"title":"Kontrak Telah Diperbaharui!","messages":"Mba Annisa D Telah memperbaharui kontrak dengan Nomor SP-56\\/VIII\\/2024 Silahkan review kembali. Terimakasih!","url":"http:\\/\\/127.0.0.1:8000\\/showUpdateKontrak\\/8"}', '2024-05-27 07:16:11', '2024-05-27 07:12:21', '2024-05-27 07:16:11'),
	('e498a886-eb2f-490b-9964-d742ec7a67d9', 'App\\Notifications\\inputKontrakNotification', 'App\\Models\\User', 1, '{"title":"Kontrak Baru Telah Dibuat!","messages":"Mba Annisa D Telah membuat kontrak baru, silahkan melakukan review. Terimakasih!","url":"http:\\/\\/127.0.0.1:8000\\/Kontrakshow1\\/2"}', '2024-05-21 02:37:23', '2024-05-21 02:36:10', '2024-05-21 02:37:23'),
	('eb3a07c2-72f5-494b-8f4d-ca3f69ee4aac', 'App\\Notifications\\RevisiKontrakNotification', 'App\\Models\\User', 5, '{"kontraks_id":"2","user_id":17,"title":"Ada Revisi Kontrak!","messages":"Mba Dini Memberikan Revisi pada Kontrak","url":"http:\\/\\/127.0.0.1:8000\\/showRevisiNotif\\/2"}', NULL, '2024-05-27 04:04:46', '2024-05-27 04:04:46'),
	('f71960cb-0703-4a0e-81af-3f2933cf16ce', 'App\\Notifications\\NetkontrakNotification', 'App\\Models\\User', 17, '{"title":"Kontrak Telah Disetujui (NET KADIV)!","kontrak":7,"messages":"Kontrak dengan Nomor SP-12\\/VIII\\/2024 Telah di Approved NET Oleh  Pa Rezi Selaku kadiv. Terimakasih!","url":"http:\\/\\/127.0.0.1:8000\\/showKontrakNotif\\/7"}', NULL, '2024-05-27 02:35:17', '2024-05-27 02:35:17'),
	('f7a6d944-17c3-4ef6-bbe8-d9baa1d03751', 'App\\Notifications\\RevisiKontrakNotification', 'App\\Models\\User', 17, '{"kontraks_id":"7","user_id":8,"title":"Ada Revisi Kontrak!","messages":"Pa Rezi Memberikan Revisi pada Kontrak","url":"http:\\/\\/127.0.0.1:8000\\/showRevisiNotif\\/7"}', NULL, '2024-05-27 02:31:17', '2024-05-27 02:31:17'),
	('fb273fac-19b3-41cc-95ba-2af4bb9b90e3', 'App\\Notifications\\UpdateKontrakNotification', 'App\\Models\\User', 17, '{"title":"Kontrak Telah Diperbaharui!","messages":"Mba Annisa D Telah memperbaharui kontrak dengan Nomor SP-12\\/VIII\\/2024 Silahkan review kembali. Terimakasih!","url":"http:\\/\\/127.0.0.1:8000\\/showUpdateKontrak\\/7"}', '2024-05-27 02:29:13', '2024-05-27 02:28:47', '2024-05-27 02:29:13');
INSERT INTO `pasal-kontrak` (`id`, `nama_pasal`, `keterangan_pasal`, `isi_pasal`, `status_jaminan`, `jenis_kontrak`, `urutan`, `created_at`, `updated_at`) VALUES
	(1, 'PASAL 1', 'DEFINISI-DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah Pengadaan barang yang harus diadakan dan dipasok oleh PIHAK KEDUA.</li><li style="text-align: justify;"><b>Spesifikasi</b> <b>Teknis</b> adalah Spesifikasi Teknis barang yang telah disepakati bersama oleh para pihak sebagaimana dimaksud dalam Lampiran III Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify;"><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 24 terpenuhi.</li><li style="text-align: justify; "><b>Surat Penerimaan Barang (SPB)</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify;"><b>Jaminan Mutu</b> adalah kewajiban PIHAK KEDUA untuk menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Perjanjian ini.</li></ol>', 1, 2, 1, '2024-03-08 06:04:11', '2024-05-27 09:21:53'),
	(2, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini. </li><li style="text-align: justify;">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.</li></ol>', 1, 2, 2, '2024-03-08 06:04:11', '2024-05-27 07:42:38'),
	(3, 'PASAL 3', 'LINGKUP PERJANJIAN', 'Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.', 1, 2, 3, '2024-03-08 06:04:11', '2024-05-27 07:43:00'),
	(4, 'PASAL 4', 'SPESIFIKASI TEKNIS', 'Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.', 1, 2, 4, '2024-03-08 06:04:11', '2024-05-27 07:43:23'),
	(5, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', 'Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.', 1, 2, 5, '2024-03-08 06:04:11', '2024-05-27 07:43:34'),
	(6, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA.</li><li style="text-align: justify;">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n</li></ol>', 1, 2, 6, '2024-03-08 06:04:11', '2024-05-27 07:43:50'),
	(7, 'PASAL 8', 'HARGA BARANG', 'Harga barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 1, 2, 8, '2024-03-08 06:26:53', '2024-05-27 07:38:47'),
	(8, 'PASAL 9', 'JAMINAN PELAKSANAAN', '<div style="text-align: justify;"><ol><li>PIHAK KEDUA harus menyerahkan kepada PIHAK KESATU Jaminan Bank untuk Jaminan Pelaksanaan (Performance Bond) dari Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga barang secara keseluruhan seperti dimaksud Pasal 8 Perjanjian ini.</li><li>Jaminan Pelaksanaan yang dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li><li>Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.</li><li>Apabila PIHAK KEDUA baik lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li>Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li>Jaminan Pelaksanaan dimaksud ayat (1) dan (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li></ol><div><br></div></div>', 1, 2, 9, '2024-03-08 06:26:53', '2024-05-27 07:41:04'),
	(9, 'PASAL 10', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<div style="text-align: justify;"><ol><li>PIHAK KEDUA harus menyerahkan kepada PIHAK KESATU Jaminan Bank untuk Jaminan Pelaksanaan (Performance Bond) dari Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga barang secara keseluruhan seperti dimaksud Pasal 8 Perjanjian ini.</li><li>Jaminan Pelaksanaan yang dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li><li>Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.</li><li>Apabila PIHAK KEDUA baik lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li>Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li>Jaminan Pelaksanaan dimaksud ayat (1) dan (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li></ol></div>', 1, 2, 10, '2024-03-08 06:26:53', '2024-05-27 07:45:17'),
	(10, 'PASAL 11', 'PEMBAYARAN', '<p style="text-align: justify; ">Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.<br></p>', 1, 2, 11, '2024-03-08 06:29:46', '2024-05-27 07:45:45'),
	(11, 'PASAL 12', 'PENYERAHAN PELAKSANAAN PEKERJAAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan pekerjaan sebagaimana dimaksud Pasal 3 Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga.</li><li style="text-align: justify;">PIHAK KEDUA dapat mengalihkan pelaksanaan pekerjaan baik sebagian maupun keseluruhan kepada pihak ketiga yang disebabkan oleh suatu hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 17 Perjanjian ini, setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah mendapatkan persetujuan dari PIHAK KESATU, maka :<ul><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh terhadap mutu Pekerjaan sebagaimana Perjanjian ini.</li><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila Pekerjaan yang dialihkan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA harus mengawasi Pekerjaan pihak ketiga atas Pekerjaan yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan Pekerjaan dalam Perjanjian ini.</li></ul></li><li style="text-align: justify;">Apabila ketentuan ayat (1), ayat (2) dan ayat (3) Pasal ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 1, 2, 12, '2024-03-08 06:29:46', '2024-05-27 07:47:29'),
	(12, 'PASAL 13', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.</li><li style="text-align: justify; ">Jika terdapat perubahan lingkup pelaksanaan sebagaimana dimaksud ayat (1) yang mengakibatkan pada penambahan atau pengurangan harga dan/atau perubahan jadwal penyerahan barang pada Surat Order Pembelian (SOP), maka akan dilakukan penyesuaian harga  dan/atau jadwal penyerahan barang pada Surat Order Pembelian (SOP), yang akan dituangkan dalam suatu surat perubahan Surat Order Pembelian (SOP) dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify;">Harga satuan pesanan tambah kurang dalam Surat Order Pembelian (SOP) tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 8 Perjanjian ini.</li><li style="text-align: justify;">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.\r\n</li></ol>', 1, 2, 13, '2024-03-08 06:38:51', '2024-05-27 07:48:40'),
	(13, 'PASAL 14', 'JAMINAN MUTU BARANG', '<div style="text-align: justify;"><ol><li>PIHAK KEDUA memberikan jaminan mutu (garansi) atas barang bahwa barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.</li><li>Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li>Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li>Dalam hal terjadi ketidaksesuaian mutu atas barang dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.</li></ol><div>Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.</div><div><br></div></div>', 1, 2, 14, '2024-03-08 06:38:51', '2024-05-27 07:51:09'),
	(14, 'PASAL 15', 'JAMINAN HUKUM ATAS BARANG', '<div style="text-align: justify;"><ol><li><span style="font-size: 1rem;">PIHAK KEDUA menjamin bahwa barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</span></li><li>PIHAK KEDUA menjamin bahwa barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li>Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.</li><li>Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.</li></ol><div><br></div></div>', 1, 2, 15, '2024-03-08 06:38:51', '2024-05-27 07:52:24'),
	(15, 'PASAL 16', 'SANKSI', '<ol><li style="text-align: justify; ">Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga barang seperti yang dimaksud Pasal 8 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/membatalkan Perjanjian ini serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 14 Perjanjian ini, dan atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/membatalkan Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Ketentuan sanksi seperti yang dimaksud Pasal ini tidak berlaku apabila :</span></div><ul><li style="text-align: justify;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.</li><li style="text-align: justify;">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 14 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.</li></ul></li></ol><div style="text-align: justify;"><br></div>', 1, 2, 16, '2024-03-08 06:38:51', '2024-05-27 09:22:39'),
	(16, 'PASAL 17', 'KEADAAN MEMAKSA', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :</span></div><ul><li style="text-align: justify;">Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</li><li style="text-align: justify;">Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</li><li style="text-align: justify;">Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.</li></ul></li><li style="text-align: justify;">Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li style="text-align: justify;">Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya yang dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.</li><li style="text-align: justify; ">Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li style="text-align: justify;">Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.</li></ol>', 1, 2, 17, '2024-03-08 06:38:51', '2024-05-27 07:57:57'),
	(17, 'PASAL 18', 'PEMBATALAN PERJANJIAN', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :</span></div><ul><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 dan 8 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 10 ayat (6) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 12 ayat (2) dan (3) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 17 ayat (2) dan (5) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.</li></ul></li><li style="text-align: justify; ">Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li style="text-align: justify; ">Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.</li><li style="text-align: justify; ">Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 2, 18, '2024-03-08 06:38:51', '2024-05-27 07:57:32'),
	(18, 'PASAL 19', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI. Arbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :</span></div><ul><li style="text-align: justify; ">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</li><li style="text-align: justify; ">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify; ">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.</li></ul></li><li style="text-align: justify;">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify;">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify;">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify; ">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify;">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify;">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify;">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 1, 2, 19, '2024-03-08 06:44:14', '2024-05-27 08:03:41'),
	(19, 'PASAL 20', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan  Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify; ">Pengecualian Informasi Ketentuan tidak berlaku dalam hal Informasi telah menjadi milik umum atau dengan lewatnya waktu 10 (sepuluh) tahun sejak penandatanganan Perjanjian ini.</li></ol>', 1, 2, 20, '2024-03-27 04:30:38', '2024-05-27 08:04:06'),
	(20, 'PASAL 21', 'PERATURAN PERUNDANG-UNDANGAN NASIONAL', '<p style="text-align: justify; ">Pihak KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah yang berlaku di Indonesia.</p>', 1, 2, 21, '2024-03-08 06:44:14', '2024-05-27 08:04:27'),
	(21, 'PASAL 22', 'HUKUM YANG BERLAKU', '<div style="text-align: justify;"><span style="font-size: 1rem;">Perjanjian   ini   tunduk   dan   berada   di   bawah ketentuan hukum Republik Indonesia.</span></div>', 1, 2, 22, '2024-03-08 06:44:14', '2024-05-27 08:05:18'),
	(22, 'PASAL 23', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify; ">Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify;">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. </li></ol>', 1, 2, 23, '2024-03-27 04:33:42', '2024-05-27 08:06:09'),
	(23, 'PASAL 24', 'TANGGAL BERLAKUNYA PERJANJIAN', '<div style="text-align: justify;"><span style="font-size: 1rem;">Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.</span></div>', 1, 2, 24, '2024-03-08 06:44:14', '2024-05-27 08:06:36'),
	(24, 'PASAL 25', 'LAMPIRAN - LAMPIRAN', '<ol><li style="text-align: justify; ">Lampiran I 	:  Dokumen-Dokumen Pengadaan</li><li style="text-align: justify;">Lampiran II	:  Lingkup Perjanjian</li><li style="text-align: justify; ">Lampiran III	:  Spesifikasi Teknis</li><li style="text-align: justify;">Lampiran IV	:  Jadwal Penyerahan Barang</li><li style="text-align: justify;">Lampiran V	:  Harga Barang</li><li style="text-align: justify;">Lampiran VI	:  Pembayaran</li><li style="text-align: justify;">Lampiran VII	:  Alamat Surat Menyurat</li></ol>', 1, 2, 25, '2024-03-08 06:45:31', '2024-05-27 08:07:08'),
	(25, 'PASAL 26', 'LAIN - LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify; ">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify;">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini. </li></ol>', 1, 2, 26, '2024-03-08 06:45:31', '2024-05-27 08:08:08'),
	(26, 'PASAL 1', 'DEFINISI-DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah Pengadaan barang yang harus diadakan dan dipasok oleh PIHAK KEDUA.</li><li style="text-align: justify;"><b>Spesifikasi Teknis</b> adalah Spesifikasi Teknis barang yang telah disepakati bersama oleh para pihak sebagaimana dimaksud dalam Lampiran III Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify; "><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 23 terpenuhi.</li><li style="text-align: justify;"><b>Surat Penerimaan Barang (SPB)</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify;"><b>Jaminan Mutu</b> adalah kewajiban PIHAK KEDUA untuk menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Perjanjian ini. \r\n</li></ol>', 2, 1, 1, '2024-03-08 07:29:06', '2024-05-27 08:15:29'),
	(29, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.</li><li style="text-align: justify;">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.\r\n</li></ol>', 2, 1, 2, '2024-03-08 07:29:23', '2024-05-27 08:18:06'),
	(30, 'PASAL 3', 'LINGKUP PERJANJIAN', '<div style="text-align: justify;"><span style="font-size: 1rem;">Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.</span></div>', 2, 1, 3, '2024-03-08 07:41:32', '2024-05-27 08:18:36'),
	(31, 'PASAL 4', 'SPESIFIKASI TEKNIS', '<div style="text-align: justify;"><span style="font-size: 1rem;">Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.</span></div>', 2, 1, 4, '2024-03-08 07:41:32', '2024-05-27 08:19:08'),
	(32, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', '<div style="text-align: justify;"><span style="font-size: 1rem;">Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.</span></div>', 2, 1, 5, '2024-03-08 07:41:32', '2024-05-27 08:19:23'),
	(33, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA.</li><li style="text-align: justify; ">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n</li></ol>', 2, 1, 6, '2024-03-08 07:41:32', '2024-05-27 08:19:54'),
	(34, 'PASAL 7', 'HARGA BARANG', 'Harga barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 2, 1, 7, '2024-03-08 07:41:32', '2024-05-27 08:20:12'),
	(35, 'PASAL 8', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<ol><li style="text-align: justify; ">Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan  kerusakan  dan/atau ketidaksesuaian spesifikasinya.</li><li style="text-align: justify;">Selanjutnya terhadap barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini akan dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.</li><li style="text-align: justify;">Apabila barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini, maka PIHAK KEDUA harus segera mengambil barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah pemberitahuan oleh PIHAK KESATU dan PIHAK KEDUA berkewajiban untuk menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu Barang sesuai dengan Pasal 13.</li><li style="text-align: justify; ">Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai spesifikasi teknis sebagaimana dimaksud dalam Pasal 4 Perjanjian ini yang mana terhadap barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.</li><li style="text-align: justify;">Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini atau persyaratan yang ditetapkan PIHAK KESATU dibuatkan Surat Penerimaan Barang (SPB) oleh Para Pihak. PIHAK KEDUA tetap harus bertanggungjawab terhadap mutu barang  seperti yang dimaksud Pasal 13 Perjanjian ini.</li><li style="text-align: justify;">Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan ayat (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (SOP) dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 8, '2024-03-08 07:41:32', '2024-05-27 08:22:04'),
	(36, 'PASAL 9', 'PEMBAYARAN', 'Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.', 2, 1, 9, '2024-03-08 07:47:13', '2024-05-27 08:22:27'),
	(37, 'PASAL 10', 'PENYERAHAN PELAKSANAAN PEKERJAAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan pekerjaan sebagaimana dimaksud Pasal 3 Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga.</li><li style="text-align: justify;">PIHAK KEDUA dapat mengalihkan pelaksanaan pekerjaan baik sebagian maupun keseluruhan kepada pihak ketiga yang disebabkan oleh suatu hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 16 Perjanjian ini, setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Apabila PIHAK KEDUA telah mendapatkan persetujuan dari PIHAK KESATU, maka :</span></div><ul><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh terhadap mutu Pekerjaan sebagaimana Perjanjian ini.</li><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila Pekerjaan yang dialihkan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA harus mengawasi Pekerjaan pihak ketiga atas Pekerjaan yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan Pekerjaan dalam Perjanjian ini.</li></ul></li><li style="text-align: justify; ">Apabila ketentuan ayat (1), ayat (2), ayat (3) Pasal ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan dan/atau mengakhiri Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 10, '2024-03-08 07:47:13', '2024-05-27 08:23:38'),
	(38, 'PASAL 11', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.</li><li style="text-align: justify; ">Jika terdapat perubahan lingkup pelaksanaan sebagaimana dimaksud ayat (1) yang mengakibatkan pada penambahan atau pengurangan harga dan/atau perubahan jadwal penyerahan barang pada Surat Order Pembelian (SOP), maka akan dilakukan penyesuaian harga  dan/atau jadwal penyerahan barang pada Surat Order Pembelian (SOP), yang akan dituangkan dalam suatu surat perubahan Surat Order Pembelian (SOP) dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify;">Harga satuan pesanan tambah kurang dalam Surat Order Pembelian (SOP) tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 7 Perjanjian ini.</li><li style="text-align: justify;">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.</li></ol>', 2, 1, 11, '2024-03-08 07:47:13', '2024-05-27 08:24:15'),
	(39, 'PASAL 12', 'JAMINAN MUTU BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA memberikan jaminan mutu (garansi) atas barang bahwa barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.</li><li style="text-align: justify;">Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li style="text-align: justify;">Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li style="text-align: justify; ">Dalam hal terjadi ketidaksesuaian mutu atas barang sebagaimana dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini. Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 2, 1, 12, '2024-03-08 07:47:13', '2024-05-27 08:24:52'),
	(40, 'PASAL 13', 'JAMINAN HUKUM ATAS BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</li><li style="text-align: justify;">PIHAK KEDUA menjamin bahwa barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li style="text-align: justify; ">Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan ayat (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.</li><li style="text-align: justify;">Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan Hukum apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 13, '2024-03-08 07:47:13', '2024-05-27 08:25:24'),
	(41, 'PASAL 14', 'SANKSI', '<ol><li style="text-align: justify; ">Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga barang sebagaimana dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/mengakhiri Perjanjian ini serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang sebagaimana dimaksud Pasal 13 Perjanjian ini, dan atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/mengakhiri Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Ketentuan sanksi sebagaimana dimaksud Pasal ini tidak berlaku apabila :<ul><li style="text-align: justify;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.</li><li style="text-align: justify;">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 13 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.</li></ul></li></ol>', 2, 1, 14, '2024-03-08 07:47:13', '2024-05-27 08:27:49'),
	(42, 'PASAL 15', 'KEADAAN MEMAKSA', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :</span></div><ul><li style="text-align: justify; ">Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</li><li style="text-align: justify; ">Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</li><li style="text-align: justify; ">Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.</li></ul></li><li style="text-align: justify;">Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li style="text-align: justify;">Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya sebagaimana dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa sebagaimana dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.</li><li style="text-align: justify; ">Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li style="text-align: justify;">Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.</li></ol>', 2, 1, 15, '2024-03-08 07:55:29', '2024-05-27 08:28:26'),
	(43, 'PASAL 16', 'PEMBATALAN PERJANJIAN', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi:</span></div><ul><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 dan 7 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 9 ayat (6) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 11 ayat (2) dan (3) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 16 ayat (2) dan (5) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang. </li></ul></li><li style="text-align: justify; ">Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li style="text-align: justify;">Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.</li><li style="text-align: justify;">Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 2, 1, 16, '2024-03-08 07:55:29', '2024-05-27 08:29:35'),
	(44, 'PASAL 17', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI.\r\nArbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut:</span></div><ul><li style="text-align: justify; ">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</li><li style="text-align: justify; ">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify; ">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.</li></ul></li><li style="text-align: justify;">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify;">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify; ">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify;">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify;">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify;">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify;">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 2, 1, 17, '2024-03-08 07:55:29', '2024-05-27 08:30:19'),
	(45, 'PASAL 18', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify;">Pengecualian Informasi Ketentuan tidak berlaku dalam hal Informasi telah menjadi milik umum atau dengan lewatnya waktu 10 (sepuluh) tahun sejak penandatanganan Perjanjian ini.</li></ol>', 2, 1, 18, '2024-03-08 07:55:29', '2024-05-27 08:30:53'),
	(46, 'PASAL 19', 'PERATURAN PERUNDANG-UNDANGAN NASIONAL', 'PIHAK KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah yang berlaku di Indonesia.', 2, 1, 19, '2024-03-08 07:55:29', '2024-05-27 08:31:10'),
	(47, 'PASAL 20', 'HUKUM YANG BERLAKU', 'Perjanjian   ini   tunduk   dan   berada   di   bawah ketentuan hukum Republik Indonesia.', 2, 1, 20, '2024-03-08 07:55:29', '2024-05-27 08:31:22'),
	(48, 'PASAL 21', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify;">Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify;">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. </li></ol>', 2, 1, 21, '2024-03-08 07:58:04', '2024-05-27 08:31:39'),
	(49, 'PASAL 22', 'TANGGAL BERLAKUNYA PERJANJIAIN', 'Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.', 2, 1, 22, '2024-03-08 07:58:04', '2024-05-27 08:31:55'),
	(50, 'PASAL 23', 'LAMPIRAN - LAMPIRAN', '<ol><li style="text-align: justify; ">Lampiran I 	:  Dokumen-Dokumen Pengadaan</li><li style="text-align: justify;">Lampiran II	:  Lingkup Perjanjian</li><li style="text-align: justify; ">Lampiran III	:  Spesifikasi Teknis</li><li style="text-align: justify;">Lampiran IV	:  Jadwal Penyerahan Barang</li><li style="text-align: justify;">Lampiran V	:  Harga Barang</li><li style="text-align: justify;">Lampiran VI	:  Pembayaran</li><li style="text-align: justify;">Lampiran VII	:  Alamat Surat Menyurat\r\n</li></ol>', 2, 1, 23, '2024-03-08 07:58:04', '2024-05-27 08:32:07'),
	(51, 'PASAL 24', 'LAIN - LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify;">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify;">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 2, 1, 24, '2024-03-08 07:58:04', '2024-05-27 08:32:25'),
	(60, 'PASAL 7', 'MASA BERLAKU PERJANJIAN', '<p>Masa berlaku Perjanjian ini terhitung sejak tanggal 27 Februari 2024 sampai dengan 31 Desember 2024, kecuali Para Pihak sepakat untuk mengakhiri atau memperpanjang masa berlakunya Perjanjian ini.<br></p>', 1, 2, 7, '2024-05-27 07:35:52', '2024-05-27 07:35:52'),
	(61, 'PASAL 1', 'DEFINISI - DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah Pengadaan barang yang harus diadakan dan dipasok oleh PIHAK KEDUA.</li><li style="text-align: justify;"><b>Spesifikasi Teknis</b> adalah Spesifikasi Teknis barang yang telah disepakati bersama oleh para pihak sebagaimana dimaksud dalam Lampiran III Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify;"><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 23 terpenuhi.</li><li style="text-align: justify;"><b>Surat Penerimaan Barang (SPB)</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify; "><b>Jaminan Mutu</b> adalah kewajiban PIHAK KEDUA untuk menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Perjanjian ini.</li></ol>', 1, 1, 1, '2024-05-27 08:35:34', '2024-05-27 08:39:31'),
	(62, 'PASAL 2', 'KETENTUAN - KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.</li><li style="text-align: justify; ">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.</li></ol>', 1, 1, 2, '2024-05-27 08:37:32', '2024-05-27 08:39:53'),
	(63, 'PASAL 3', 'LINGKUP PERJANJIAN', '<p>Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.<br></p>', 1, 1, 3, '2024-05-27 08:38:21', '2024-05-27 08:38:21'),
	(64, 'PASAL 4', 'SPESIFIKASI TEKNIS', '<p>Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.<br></p>', 1, 1, 4, '2024-05-27 08:38:54', '2024-05-27 08:38:54'),
	(65, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', '<p style="text-align: justify; ">Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.<br></p>', 1, 1, 5, '2024-05-27 08:40:50', '2024-05-27 08:40:50'),
	(66, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA.</li><li style="text-align: justify; ">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 1, 1, 6, '2024-05-27 08:42:29', '2024-05-27 08:42:29'),
	(67, 'PASAL 7', 'HARGA BARANG', '<p>Harga barang sebagaimana tercantum dalam Lampiran V Perjanjian ini.</p>', 1, 1, 7, '2024-05-27 08:43:01', '2024-05-27 08:43:01'),
	(68, 'PASAL 8', 'JAMINAN PELAKSANAAN', '<ol><li style="text-align: justify; ">PIHAK KEDUA harus menyerahkan kepada PIHAK KESATU Jaminan Bank untuk Jaminan Pelaksanaan (Performance Bond) dari Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga Barang secara keseluruhan seperti dimaksud Pasal 7 Perjanjian ini.</li><li style="text-align: justify; ">Jaminan Pelaksanaan yang dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li><li style="text-align: justify; ">Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA baik lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Jaminan Pelaksanaan dimaksud ayat (1) dan (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan Surat Penerimaan Barang (SPB).</li></ol>', 1, 1, 8, '2024-05-27 08:45:59', '2024-05-27 08:45:59'),
	(69, 'PASAL 9', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<ol><li style="text-align: justify; ">Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan kerusakan dan atau ketidaksesuaian spesifikasinya.</li><li style="text-align: justify; ">Selanjutnya terhadap barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.</li><li style="text-align: justify; ">Apabila barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini, maka PIHAK KEDUA harus segera mengambil barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah pemberitahuan oleh PIHAK KESATU dan harus menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu Barang sesuai dengan Pasal 13.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai spesifikasi teknis sebagaimana dimaksud dalam Pasal 4 Perjanjian ini yang mana terhadap barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.</span></div><li style="text-align: justify; ">Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan spesifikasi teknis sebagaimana dimaksud Pasal 4 Perjanjian ini atau persyaratan yang ditetapkan PIHAK KESATU dibuatkan Surat Penerimaan Barang (SPB) oleh Para Pihak tetap harus bertanggungjawab terhadap mutu barang seperti yang dimaksud Pasal 13 Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (SOP) dan atau Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li></li></ol>', 1, 1, 9, '2024-05-27 08:49:01', '2024-05-27 08:49:01'),
	(70, 'PASAL 10', 'PEMBAYARAN', '<p>Pembayaran&nbsp; dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.</p>', 1, 1, 10, '2024-05-27 08:49:51', '2024-05-27 08:49:51'),
	(71, 'PASAL 11', 'PENYERAHAN PELAKSANAAN PEKERJAAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan pekerjaan dimaksud Pasal 3 Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga.</li><li style="text-align: justify; ">PIHAK KEDUA dapat mengalihkan pelaksanaan pekerjaan baik sebagian maupun keseluruhan kepada pihak ketiga yang disebabkan oleh suatu hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 16 Perjanjian ini, setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Apabila PIHAK KEDUA telah mendapatkan persetujuan dari PIHAK KESATU, maka :</span></div><ul><li><div style="text-align: justify;"><span style="font-size: 1rem;">PIHAK KEDUA bertanggungjawab penuh terhadap mutu Pekerjaan sebagaimana Perjanjian ini.</span></div><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila Pekerjaan yang dialihkan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA harus mengawasi Pekerjaan pihak ketiga atas Pekerjaan yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan Pekerjaan dalam Perjanjian ini.</li></li></ul></li><li style="text-align: justify; "><span style="font-size: 1rem;">Apabila ketentuan ayat (1), ayat (2) dan ayat (3) Pasal ini dilanggar oleh PIHAK KEDUA, maka&nbsp;</span>PIHAK KESATU secara sepihak berhak membatalkan Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li></ol>', 1, 1, 11, '2024-05-27 08:54:41', '2024-05-27 08:54:41'),
	(72, 'PASAL 12', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.</li><li style="text-align: justify; ">Jika perubahan dalam ayat (1) Pasal ini mengakibatkan penambahan atau pengurangan harga dan atau perubahan jadwal penyerahan barang pada Surat Order Pembelian (SOP), maka akan dilakukan penyesuaian harga dan atau jadwal penyerahan barang pada Surat Order Pembelian (SOP), yang akan dituangkan dalam suatu surat perubahan Surat Order Pembelian (SOP) dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify; ">Harga satuan pesanan tambah kurang dalam Surat Order Pembelian (SOP) tidak boleh melebihi dari harga satuan yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 7 Perjanjian ini.</li><li style="text-align: justify; ">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.</li></ol>', 1, 1, 12, '2024-05-27 08:56:30', '2024-05-27 08:56:30'),
	(73, 'PASAL 13', 'JAMINAN MUTU BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA memberikan jaminan mutu (garansi) atas barang bahwa barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya</li><li style="text-align: justify; ">Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li style="text-align: justify; ">Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li style="text-align: justify; ">Dalam hal terjadi ketidaksesuaian mutu atas barang dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini. Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 1, 13, '2024-05-27 08:58:36', '2024-05-27 08:58:36'),
	(74, 'PASAL 14', 'JAMINAN HUKUM ATAS BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</li><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li style="text-align: justify; ">Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.</li><li style="text-align: justify; ">Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.</li></ol>', 1, 1, 14, '2024-05-27 08:59:55', '2024-05-27 08:59:55'),
	(75, 'PASAL 15', 'SANKSI', '<ol><li style="text-align: justify; "><span style="font-size: 1rem;">Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui&nbsp;</span>maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga barang seperti yang dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/membatalkan Perjanjian ini serta Jaminan Pelaksanaan (Performance Bond) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 13 Perjanjian ini, dan atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/membatalkan Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Ketentuan sanksi seperti yang dimaksud Pasal ini tidak berlaku apabila :</span></div><ul><li style="text-align: justify; "><span style="font-size: 1rem;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara&nbsp;</span>tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.</li><li style="text-align: justify; ">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 13 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.</li></ul></li></ol>', 1, 1, 15, '2024-05-27 09:03:48', '2024-05-27 09:03:48'),
	(76, 'PASAL 16', 'KEADAAN MEMAKSA', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :</span></div><ul><li style="text-align: justify; ">Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</li><li style="text-align: justify; ">Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</li><li style="text-align: justify; ">Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.</li></ul></li><li style="text-align: justify; ">Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li style="text-align: justify; ">Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya yang dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.</li><li style="text-align: justify; ">Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li style="text-align: justify; ">Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.</li></ol>', 1, 1, 16, '2024-05-27 09:06:33', '2024-05-27 09:06:33'),
	(77, 'PASAL 17', 'PEMBATALAN PERJANJIAN', '<ol><li><div style="text-align: justify;"><span style="font-size: 1rem;">PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :</span></div><ul><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 dan 7 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 9 ayat (6) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 11 ayat (2) dan (3) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 16 ayat (2) dan (5) Perjanjian ini.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.</li></ul></li><li style="text-align: justify; ">Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li style="text-align: justify; ">Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.</li><li style="text-align: justify; ">Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 1, 17, '2024-05-27 09:09:02', '2024-05-27 09:09:02'),
	(78, 'PASAL 18', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI.&nbsp; Arbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :</span></div><ul><li><div style="text-align: justify;"><span style="font-size: 1rem;">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</span></div><li style="text-align: justify; ">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify; ">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.</li></li></ul></li><li style="text-align: justify; ">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify; ">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify; ">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify; ">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify; ">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify; ">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify; ">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 1, 1, 18, '2024-05-27 09:14:01', '2024-05-27 09:14:01'),
	(79, 'PASAL 19', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify; ">Pengecualian Informasi Ketentuan tidak berlaku dalam hal Informasi telah menjadi milik umum atau dengan lewatnya waktu 10 (sepuluh) tahun sejak penandatanganan Perjanjian ini.</li></ol>', 1, 1, 19, '2024-05-27 09:15:09', '2024-05-27 09:15:09'),
	(80, 'PASAL 20', 'PERATURAN PERUNDANG-UNDANGAN NASIONAL', '<p>PIHAK KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah&nbsp;<span style="font-size: 1rem;">yang berlaku di Indonesia.</span></p>', 1, 1, 20, '2024-05-27 09:15:47', '2024-05-27 09:15:47'),
	(81, 'PASAL 21', 'HUKUM YANG BERLAKU', '<p>Perjanjian ini tunduk dan berada di bawah ketentuan hukum Republik Indonesia.</p>', 1, 1, 21, '2024-05-27 09:16:19', '2024-05-27 09:16:19'),
	(82, 'PASAL 22', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify; ">Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify; ">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 1, 22, '2024-05-27 09:17:48', '2024-05-27 09:17:48'),
	(83, 'PASAL 23', 'TANGGAL BERLAKUNYA PERJANJIAN', '<p>Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.</p>', 1, 1, 23, '2024-05-27 09:18:38', '2024-05-27 09:18:38'),
	(84, 'PASAL 24', 'LAMPIRAN-LAMPIRAN', '<ol><li>Lampiran I: Dokumen-Dokumen Pengadaan</li><li>Lampiran II : Lingkup Perjanjian</li><li>Lampiran III : Spesifikasi Teknis</li><li>Lampiran IV : Jadwal Penyerahan Barang</li><li>Lampiran V : Harga Barang</li><li><span style="font-size: 1rem;">Lampiran VI&nbsp;</span>: Pembayaran</li><li><span style="font-size: 1rem;">Lampiran VII&nbsp;</span>: Alamat Surat Menyurat</li></ol>', 1, 1, 24, '2024-05-27 09:20:21', '2024-05-27 09:20:21'),
	(85, 'PASAL 25', 'LAIN-LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify; ">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify; ">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 1, 1, 25, '2024-05-27 09:21:22', '2024-05-27 09:21:22');
