INSERT INTO `vendor_texts` (`id`, `registration_no`, `akta`, `npwp`, `pihakname`, `created_at`, `updated_at`) VALUES
	(3, '00003651', '<p style="text-align: justify; ">yang dalam hal ini jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan&nbsp;<span style="font-size: 1rem;">atas nama </span>CV. GEMILANG INDO WIRATAMA<span style="font-size: 1rem;">&nbsp;yang didirikan dengan Akta Notaris Nomor : 260&nbsp;tanggal 21 November 1995 yang dibuat dihadapan Ny.Ratna Komala Komar, SH, Notaris&nbsp;</span><span style="font-size: 1rem;">di Jakarta dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 85 tanggal&nbsp;</span><span style="font-size: 1rem;">23 Desember 2016 yang dibuat dihadapan Irma Bonita, SH, Notaris di Jakarta Pusat yang&nbsp;</span><span style="font-size: 1rem;">dibuat berdasarkan Hukum Negara RI, yang berkedudukan hukum di Mega Glodok&nbsp;</span><span style="font-size: 1rem;">Kemayoran Lantai GF Blok C9 No.9 Jakarta Pusat dengan Nomor Pokok Wajib Pajak&nbsp;(NPWP) Nomor : </span>81.841.075.5-408.000<span style="font-size: 1rem;">&nbsp;yang untuk selanjutnya dalam Perjanjian ini&nbsp;disebut sebagai:</span></p><p style="text-align: center;">---------------------------------------------- PIHAK KEDUA ------------------------------------------<br></p>', '81.841.075.5-408.000', 'ARIFUL UMAM', '2024-05-21 03:20:19', '2024-05-21 03:20:19'),
	(9, '00000122', '<p style="text-align: justify;"><span style="font-size: 14px;">﻿</span><span style="font-size: 14px;">﻿</span><span style="font-size: 14px;">yang dalam hal ini jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan&nbsp;</span><span style="font-size: 14px;">atas nama PT. MANGGALA EKA SAKTI yang didirikan dengan Akta Notaris Nomor : 260&nbsp;</span><span style="font-size: 14px;">tanggal 21 November 1995 yang dibuat dihadapan Ny.Ratna Komala Komar, SH, Notaris&nbsp;</span><span style="font-size: 14px;">di Jakarta dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 85 tanggal&nbsp;</span><span style="font-size: 14px;">23 Desember 2016 yang dibuat dihadapan Irma Bonita, SH, Notaris di Jakarta Pusat yang&nbsp;</span><span style="font-size: 14px;">dibuat berdasarkan Hukum Negara RI, yang berkedudukan hukum di&nbsp;</span><span style="font-size: 14px;">Graha Yapetri Lt. IV, Jl. Sunan Kalijaga No. 65B Melawai - Jakarta Selatan, Jakarta</span><span style="font-size: 14px;">&nbsp;dengan Nomor Pokok Wajib Pajak&nbsp;(NPWP) Nomor : </span><span style="font-size: 14px;">719016842064000</span><span style="font-size: 14px;">&nbsp;yang untuk selanjutnya dalam Perjanjian ini&nbsp;disebut sebagai:</span></p><p style="text-align: center; "><span style="font-size: 14px;">---------------------------------------------- PIHAK KEDUA ------------------------------------------</span></p>', '719016842064000', 'ROY P. JONACH SIMANJUNTAK', '2024-05-28 04:07:53', '2024-05-28 04:07:53'),
	(12, '00000247', '<p style="text-align: justify; "><span style="font-size: 14px;">﻿</span><span style="font-size: 14px;">﻿</span><span style="font-size: 14px;">﻿</span><span style="font-size: 14px;">yang dalam hal ini jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan </span><span style="font-size: 14px;">atas nama PT. Gwantama Nusa Mandiri yang didirikan dengan Akta Notaris Nomor : 260 </span><span style="font-size: 14px;">tanggal 21 November 1995 yang dibuat dihadapan Ny.Ratna Komala Komar, SH, Notaris </span><span style="font-size: 14px;">di Jakarta dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 85 tanggal </span><span style="font-size: 14px;">23 Desember 2016 yang dibuat dihadapan Irma Bonita, SH, Notaris di Jakarta Pusat yang </span><span style="font-size: 14px;">dibuat berdasarkan Hukum Negara RI, yang berkedudukan hukum di Mega Glodok </span><span style="font-size: 14px;">Kemayoran Lantai GF Blok C9 No.9 Jakarta Pusat dengan Nomor Pokok Wajib Pajak (NPWP) Nomor : </span><span style="font-size: 14px;">01.746.562.6.028.000</span><span style="font-size: 14px;"> yang untuk selanjutnya dalam Perjanjian ini disebut sebagai:</span></p><p style="text-align: center;"><span style="font-size: 14px;">---------------------------------------------- PIHAK KEDUA ------------------------------------------</span><br></p>', '01.746.562.6.028.000', 'BUYUNG', '2024-05-28 08:22:02', '2024-05-28 08:22:02'),
	(14, '00001850', '<p style="text-align: justify; ">yang dalam hal ini dalam jabatannya selaku Direktur dari dan oleh karena itu&nbsp;<span style="font-size: 1rem;">bertindak untuk dan atas nama PT. Danisa Eka Abadi, yang didirikan&nbsp;</span><span style="font-size: 1rem;">berdasarkan Akta Notaris Nomor : 04 tanggal 01 Juli 2020 yang dibuat oleh&nbsp;</span><span style="font-size: 1rem;">Notaris Aisyah Ratu Juliana Siregar, S.H., M.Kn. Notaris di Kota Sukabumi&nbsp;</span><span style="font-size: 1rem;">dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 062&nbsp;</span><span style="font-size: 1rem;">tanggal 04 Agustus 2023 yang dibuat oleh Notaris Dwi Suswanti, S.H., M.Kn.&nbsp;</span><span style="font-size: 1rem;">Notaris di Kota Cilegon yang dibuat berdasarkan Hukum Negara Republik&nbsp;</span><span style="font-size: 1rem;">Indonesia, yang berkedudukan hukum di Jalan Sultan Iskandar Muda No. 181&nbsp;</span><span style="font-size: 1rem;">Kota Administrasi Jakarta Selatan, dengan Nomor Pokok Wajib Pajak&nbsp;(NPWP) Nomor: </span>95.258.793.9-013.000<span style="font-size: 1rem;">&nbsp;yang untuk selanjutnya dalam&nbsp;perbuatan&nbsp;</span><span style="font-size: 1rem;">hukum&nbsp;</span><span style="font-size: 1rem;">ini&nbsp;</span><span style="font-size: 1rem;">disebut&nbsp;</span><span style="font-size: 1rem;">sebagai&nbsp;</span><span style="font-size: 1rem;">:</span></p><p style="text-align: center; "><b>-------------------------------------- PIHAK KEDUA ----------------------------------</b><br></p>', '95.258.793.9-013.000', 'Cecep Hidayat', '2024-05-28 08:26:32', '2024-05-28 08:26:32');
